def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # The large, repeated colors form the objects; rare colors are noise.
    object_colors = {color for color, n in counts.items()
                     if color != bg and n >= 4}

    out = [[v if v in object_colors else bg for v in row] for row in grid]
    for color in object_colors:
        seen = [[False] * w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                if out[r][c] != color or seen[r][c]:
                    continue
                q = deque([(r, c)])
                seen[r][c] = True
                cells = []
                while q:
                    y, x = q.popleft()
                    cells.append((y, x))
                    for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                        if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                                and out[ny][nx] == color):
                            seen[ny][nx] = True
                            q.append((ny, nx))
                if len(cells) >= 4:
                    r1, r2 = min(y for y, x in cells), max(y for y, x in cells)
                    c1, c2 = min(x for y, x in cells), max(x for y, x in cells)
                    for y in range(r1, r2 + 1):
                        for x in range(c1, c2 + 1):
                            out[y][x] = color
    return out
